import sys
from bisect import bisect_left


class FenwickMax:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def update(self, i, value):
        while i <= self.n:
            if value > self.bit[i]:
                self.bit[i] = value
            i += i & -i

    def query(self, i):
        res = 0
        while i > 0:
            if self.bit[i] > res:
                res = self.bit[i]
            i -= i & -i
        return res


def main():
    input = sys.stdin.readline

    N, Q = map(int, input().split())
    A = list(map(int, input().split()))

    values = sorted(set(A))
    by_value = FenwickMax(len(values))
    dp = [0] * N

    for i, a in enumerate(A):
        idx = bisect_left(values, a) + 1
        dp[i] = by_value.query(idx - 1) + 1
        by_value.update(idx, dp[i])

    points = sorted((A[i], i + 1, dp[i]) for i in range(N))

    queries = []
    for qi in range(Q):
        r, x = map(int, input().split())
        queries.append((x, r, qi))
    queries.sort()

    ans = [0] * Q
    by_pos = FenwickMax(N)
    p = 0

    for x, r, qi in queries:
        while p < N and points[p][0] <= x:
            _, pos, length = points[p]
            by_pos.update(pos, length)
            p += 1
        ans[qi] = by_pos.query(r)

    print("\n".join(map(str, ans)))


if __name__ == "__main__":
    main()
